      html: '\u003cdiv class="workshop-preview">\u003cdiv class="workshop-preview-tools">\u003cbutton type="button" data-workshop-menu aria-label="Mục lục">☰ Mục lục\u003c/button>\u003ca href="#p0">Báo cáo thực tập\u003c/a>\u003cspan>›\u003c/span>\u003ca href="#p17">Workshop\u003c/a>\u003cspan>› 5.11\u003c/span>\u003c/div>\u003ch1>\n              \n              Thiết lập Nginx và HTTPS theo IP\n            \u003c/h1>\n          \n\n        \n\n\n\n\t\u003cp>Mở ingress web, chuẩn bị Certbot và cài helper reconcile IP đúng source.\u003c/p>\n\u003ch3 id="các-bước-thiết-lập">Các bước thiết lập\u003c/h3>\n\u003cul>\n\u003cli>\u003ca href="#ws-5-12">5.11.1. Cấu hình cổng truy cập và Nginx\u003c/a>\u003c/li>\n\u003cli>\u003ca href="#ws-5-8-3">5.11.2. Cài Certbot và cấu hình HTTPS tự động\u003c/a>\u003c/li>\n\u003cli>\u003ca href="#ws-5-8-4">5.11.3. Kiểm tra HTTP, HTTPS và WebSocket\u003c/a>\u003c/li>\n\u003c/ul>\n\u003chr>\n\u003cp>\u003ca href="#ws-5-10">← 5.10\u003c/a> · \u003ca href="#p17">Mục lục\u003c/a> · \u003ca href="#ws-5-12-v2">5.12 →\u003c/a>\u003c/p>\n\n\n\n\n\n\u003cfooter class=" footline" >\n\t\n\u003c/footer>\u003c/div>',
